from .protocols import Ping, Ssh, HwApi

TRS_IP = '192.168.255.20'
USERNAME = 'toor4nsn'
PASSWORD = 'oZPS0POrRieRtu'


class IphyResponsiveness(object):
    def __init__(self, trs_ip=TRS_IP, username=USERNAME, password=PASSWORD):
        self._ping = Ping(trs_ip)
        self._ssh = Ssh(trs_ip, username, password)
        self._hwapi = HwApi(trs_ip)

    def wait_for_ssh(self, timeout=8 * 60):
        """Wait until SSH on I-PHY becomes available."""
        self._ssh.wait_until_passed(amount=15, timeout=timeout)

    def check_ping(self, tries=15):
        """Check if I-PHY device is pingable."""
        self._ping.run(tries=tries)

    def wait_for_hwapi(self, timeout=60):
        """Wait until HWAPI on I-PHY becomes available."""
        self._hwapi.wait_until_passed(timeout=timeout)
